const payload = $json.body ?? $json;
const inputs = payload.inputs ?? payload;
const question = String(inputs.input ?? '');
const output = String(inputs.output ?? '');
const expected = String(inputs.expected_output ?? inputs.expectedOutput ?? '');
const context = String(inputs.context ?? '');

let score = 0;
let reason = '';

if (!output.trim()) {
  score = 0;
  reason = '候选回答为空，无法通过评估。';
} else if (expected.trim() && output.includes(expected)) {
  score = 1;
  reason = '候选回答包含期望答案，满足当前 n8n 规则评估要求。';
} else if (expected.trim()) {
  score = 0.6;
  reason = '候选回答非空，但未直接命中期望答案；建议继续使用大模型评估器细化语义判断。';
} else {
  score = 0.7;
  reason = '未提供期望答案，候选回答非空，按基础规则给出通过结果。';
}

return [{
  json: {
    score,
    passed: score >= 0.6,
    reason,
    metadata: {
      evaluator: 'PA Eval n8n 工作流评估器',
      questionLength: question.length,
      outputLength: output.length,
      contextLength: context.length
    }
  }
}];
